{
  "references": [
    {"id": "R1", "summary_ko": "아이의 입이 피리에 닿거나 불고 있지 않은 것처럼 보임"},
    {"id": "R2", "summary_ko": "뱀 머리가 부자연스러워 보이고 허공에서 갑자기 더 생겨남"},
    {"id": "R3", "summary_ko": "프롬프트 내용과 달리 뱀이 구름으로 만들어진 것처럼 보이지 않음"}
  ],
  "candidates": [
    {"id": "C1", "summary_ko": "소용돌이치는 리본 형태가 저절로 나타나 떠다니는 뱀 형상으로 변함"},
    {"id": "C2", "summary_ko": "떠다니는 국수 형태가 늘어나고 루프를 돌며 비일관적으로 뱀 머리와 꼬리를 형성하고 위상이 변함"},
    {"id": "C3", "summary_ko": "초반에 피리가 소년의 입과 손에 상대적인 위치에서 갑작스럽게 이동함"}
  ],
  "pairs": [
    {"reference_id": "R1", "candidate_id": "C1", "verdict": "different", "reason_ko": "아이의 입과 피리 접촉 문제와 리본이 뱀으로 변형되는 현상은 서로 다른 대상을 다룹니다."},
    {"reference_id": "R1", "candidate_id": "C2", "verdict": "different", "reason_ko": "아이의 피리 부는 동작 문제와 뱀 형상의 변형 문제는 서로 다른 대상을 다룹니다."},
    {"reference_id": "R1", "candidate_id": "C3", "verdict": "uncertain", "reason_ko": "둘 다 입과 피리의 불일치에 관련된 현상이지만, 입이 닿지 않는다는 설명과 피리의 위치가 급변한다는 설명의 일치 여부가 불분명합니다."},
    {"reference_id": "R2", "candidate_id": "C1", "verdict": "uncertain", "reason_ko": "뱀 머리가 허공에서 나타난다는 점과 리본 형태에서 뱀 형상이 나타난다는 점이 부분적으로 연관될 수 있으나 동일한 결함인지 모호합니다."},
    {"reference_id": "R2", "candidate_id": "C2", "verdict": "same", "reason_ko": "뱀 머리가 부자연스럽게 생겨나고 늘어나는 현상을 동일하게 설명하고 있습니다."},
    {"reference_id": "R2", "candidate_id": "C3", "verdict": "different", "reason_ko": "뱀 머리 생성 결함과 피리의 위치 변화 문제는 서로 다른 결함입니다."},
    {"reference_id": "R3", "candidate_id": "C1", "verdict": "different", "reason_ko": "구름 재질 프롬프트 미준수 결함과 리본의 뱀 변형 현상은 서로 다른 결함입니다."},
    {"reference_id": "R3", "candidate_id": "C2", "verdict": "different", "reason_ko": "프롬프트의 구름 질감 미반영 문제와 국수 형태의 뱀 변형 문제는 서로 다른 내용을 다룹니다."},
    {"reference_id": "R3", "candidate_id": "C3", "verdict": "different", "reason_ko": "구름 재질 문제와 피리의 위치 문제는 서로 다른 대상을 다룹니다."}
  ]
}
